const BASE=TOPICS.slice();
const CL_MAX_LISTS=12,CL_MAX_WORDS=30,CL_MIN_WORDS=4;
let clSig=null;
function syncCustom(){const sig=ALL.cur+'|'+JSON.stringify(S.custom||[]);if(sig===clSig)return;clSig=sig;
  TOPICS.length=0;BASE.forEach(t=>TOPICS.push(t));Object.keys(WMAP).forEach(k=>{if(k.startsWith('my-'))delete WMAP[k]});
  (S.custom||[]).forEach(c=>{const id='my-'+c.id;const t={id,custom:c.id,only:c.lang,zh:c.name,en:c.name,ms:c.name,tag:'',icon:'📝',hue:'var(--custom)',sent:null};
    t.words=c.words.map(a=>({e:a.e||'',en:c.lang==='en'?a.w:'',ms:c.lang==='ms'?a.w:'',zh:a.zh||'',k:a.w,t:id}));
    TOPICS.push(t);t.words.forEach(w=>WMAP[id+':'+w.k]=w)})}
function findBuiltin(word){const x=word.toLowerCase();for(const t of BASE)for(const w of t.words)if(w.en.toLowerCase()===x||w.ms.toLowerCase()===x)return w;return null}
function parseWords(txt){const out=[],bad=[];
  String(txt||'').split(/\n/).forEach(line=>{line=line.trim();if(!line)return;
    const parts=line.split(/[,，|\t=、;；]+/).map(x=>x.trim()).filter(Boolean);let w='',zh='',e='';
    parts.forEach(p=>{if(/\p{Extended_Pictographic}/u.test(p)&&!/[A-Za-z\u3400-\u9fff]/.test(p)){if(!e)e=p}else if(/[\u3400-\u9fff]/.test(p)){if(!zh)zh=p.slice(0,12)}else if(!w)w=p.replace(/\s+/g,' ').slice(0,30)});
    if(!w||!/[A-Za-z]/.test(w)){bad.push(line+'  ← 找不到英文/国文单词');return}
    if(!e){const m=findBuiltin(w);if(m){e=m.e;zh=zh||m.zh}}
    if(!e&&!zh){bad.push(line+'  ← 请加上中文意思或一个表情图');return}
    if(out.some(o=>o.w.toLowerCase()===w.toLowerCase()))return;
    if(out.length>=CL_MAX_WORDS){bad.push(line+'  ← 一个词表最多 '+CL_MAX_WORDS+' 个词');return}
    out.push({w,zh,e})});
  return{out,bad}}
